from pathlib import Path
import csv,json,re

rows=[]
with open(\"ortg.tsv\",encoding=\"utf-8\",newline=\"\") as f:
    for _ in range(22): next(f)
    for r in csv.DictReader(f,delimiter=\"\\t\"):
        p=r[\"path\"]
        explicit=(p==\"CHANGES.rst\" or (p.startswith(\"astropy/wcs/tests/data/validate.\") and p.endswith(\".txt\")) or p==\"astropy/wcs/wcsapi/data/ucds.txt\")
        if not r[\"outline\"] and r[\"ignored\"]==\"0\" and r[\"deleted\"]==\"0\" and Path(p).is_file() and (p.startswith(\"docs/\") or explicit):
            rows.append(p)

binary_ext={\".png\",\".ico\",\".pdf\",\".odg\"}
def clean(s):
    s=re.sub(r\":[a-zA-Z0-9_-]+:\",\"\",s)
    s=re.sub(r\"\\s+\",\" \",s).strip(\" #*|\")
    return s

def text_info(p):
    path=Path(p); ext=path.suffix.lower()
    data=path.read_bytes()
    if ext in binary_ext:
        return \"\",[],len(data)
    txt=data.decode(\"utf-8\",\"replace\")
    lines=txt.splitlines()
    heads=[]
    marks=set(\"=-~"'^'"\\\"':+*#\")
    for i,line in enumerate(lines[:-1]):
        a=clean(line)
        b=lines[i+1].strip()
        if a and len(a)<=140 and b and set(b)<=marks and len(b)>=max(3,len(line.strip())-2):
            if a not in heads: heads.append(a)
    for line in lines:
        m=re.match(r\"\\s*\\.\\.\\s+(?:automodule|autoclass|autofunction|currentmodule)::\\s*(.+)\",line)
        if m:
            v=clean(m.group(1))
            if v and v not in heads: heads.append(v)
    return txt,heads,len(lines)

def title_for(p,txt,heads):
    path=Path(p)
    if heads: return heads[0]
    for line in txt.splitlines():
        s=clean(line)
        if not s or s.startswith((\".. \",\".._\",\"<\",\"{\",\"%\",\"/*\",\"//\")): continue
        if len(s)>=4: return s[:140]
    return path.stem.replace(\"_\",\" \").replace(\"-\",\" \")

def outline(p):
    path=Path(p); ext=path.suffix.lower()
    txt,heads,measure=text_info(p)
    title=title_for(p,txt,heads)
    low=p.lower()
    if p==\"CHANGES.rst\":
        role=\"汇总 Astropy 各版本发布说明、API 变更、新功能、修复与弃用记录\"
    elif \"/changes/\" in low:
        role=f\"记录待发布变更“{title}”\"
    elif \"/whatsnew/\" in low:
        role=f\"说明 Astropy {title} 版本的重要变化与迁移信息\"
    elif \"/_static/\" in low:
        kind={\".svg\":\"矢量图形\",\".png\":\"位图\",\".ico\":\"站点图标\",\".pdf\":\"可打印图形\",\".css\":\"样式表\"}.get(ext,\"静态资源\")
        role=f\"提供 Astropy 文档站点使用的{kind}“{path.stem}”\"
    elif \"/_templates/\" in low:
        role=f\"定义 Astropy 文档站点的 Sphinx 页面模板“{path.stem}”\"
    elif p==\"docs/Makefile\" or p==\"docs/make.bat\":
        role=\"提供调用 Sphinx 构建 Astropy 文档的命令入口\"
    elif p.startswith(\"astropy/wcs/tests/data/validate.\"):
        role=f\"保存 WCS 校验测试的参考诊断输出“{path.name}”\"
    elif p==\"astropy/wcs/wcsapi/data/ucds.txt\":
        role=\"列出 WCS API 识别的 UCD1+ 物理类型词汇及说明\"
    elif ext in {\".png\",\".odg\",\".csv\"}:
        role=f\"提供“{path.stem}”文档示例使用的素材或样例数据\"
    elif \"/examples/\" in low and ext==\".py\":
        role=f\"演示 Astropy 文档主题“{title}”的可运行示例\"
    else:
        topics=\"、\".join(heads[1:4])
        role=f\"说明“{title}”\"
        if topics: role+=f\"，涵盖{topics}\"
    role=clean(role)[:300] or f\"说明文档资源“{path.name}”\"

    constraints=[]
    if txt:
        paras=re.split(r\"\\n\\s*\\n\",txt)
        key=re.compile(r\"\\b(must|must not|should|should not|required|requires|only|cannot|do not|never|deprecated|warning)\\b\",re.I)
        for para in paras:
            s=clean(para)
            if key.search(s) and 12<=len(s)<=700 and not s.startswith(\".. _\"):
                constraints.append(s)
                if sum(len(x) for x in constraints)>=430 or len(constraints)>=2: break
    if p.startswith(\"astropy/wcs/tests/data/validate.\"):
        constraints=[\"内容是测试比较基准，诊断顺序、缩进、关键字与数值文本均属于夹具契约\"]
    elif p==\"astropy/wcs/wcsapi/data/ucds.txt\":
        constraints=[\"每个有效条目以 UCD 词和英文说明构成；空行及井号注释不作为词汇\"]
    elif ext in binary_ext or \"/_static/\" in low:
        constraints=[\"文件路径与格式由文档构建或页面模板引用，替换时须保持引用兼容\"] if p.startswith(\"docs/\") else []
    cons=\"；\".join(constraints)[:600] if constraints else \"-\"
    n=measure
    size=\"L\" if n>400 else \"M\" if n>=200 else \"S\" if n>=100 else \"T\"
    imp=\"8\" if path.name in {\"index.rst\",\"install.rst\",\"CHANGES.rst\"} else \"3\" if \"/_static/\" in low else \"5\"
    return f\"{path.name}[{imp} O G {size}]: Role:{role} | Uses:- | API:- | Constraints:{cons}\"

print(json.dumps([{\"path\":p,\"outline\":outline(p)} for p in rows],ensure_ascii=False))

PY"

