from pathlib import Path
import ast,csv,json,re,sys
limit=int(sys.argv[1]) if len(sys.argv)>1 else 160
rows=[]
with open(\"ortg.tsv\",encoding=\"utf-8\",newline=\"\") as f:
    for _ in range(22): next(f)
    for r in csv.DictReader(f,delimiter=\"\\t\"):
        p=Path(r[\"path\"])
        if not r[\"outline\"] and r[\"ignored\"]==\"0\" and r[\"deleted\"]==\"0\" and p.is_file(): rows.append(str(p))
rows=rows[:limit]
all_paths=set()
with open(\"ortg.tsv\",encoding=\"utf-8\",newline=\"\") as f:
    for _ in range(22): next(f)
    for r in csv.DictReader(f,delimiter=\"\\t\"):
        if r[\"ignored\"]==\"0\" and r[\"deleted\"]==\"0\": all_paths.add(r[\"path\"])
test_paths=[p for p in all_paths if \"/tests/\" in p and p.endswith(\".py\") and Path(p).is_file()]
test_text={}; test_tree={}
for p in test_paths:
    txt=Path(p).read_text(encoding=\"utf-8\",errors=\"replace\"); test_text[p]=txt
    try: test_tree[p]=ast.parse(txt)
    except SyntaxError: pass
def clean(s,n=400):
    s=str(s or \"\").replace(\"|\",\"¦\").replace(\"\\t\",\" \")
    s=re.sub(r\"\\s+\",\" \",s).strip(\" #*\")
    return s[:n]
def first_sentence(s):
    s=clean(s,1000)
    if not s: return \"\"
    return clean(re.split(r\"(?<=[."'!?。！？])'"\\s+\",s)[0],300)
def module_for(p):
    parts=Path(p).parts
    if not parts: return \"G\"
    if parts[0]==\"cextern\": return \"CE\"
    if parts[0]"'!="astropy": return "BG"
    if len(parts)<2: return "G"
    top=parts[1]
    fixed={"config":"CF","constants":"CN","convolution":"CV","coordinates":"CO","cosmology":"CS","extern":"EX","modeling":"MD","nddata":"ND","uncertainty":"UC","samp":"SA","stats":"ST","table":"TB","time":"TI","timeseries":"TS","units":"UN","utils":"UT","visualization":"VI","wcs":"WC","tests":"G"}
    if top=="io":
        if len(parts)>2: return {"ascii":"AS","fits":"FI","misc":"MS","registry":"RG","votable":"VO"}.get(parts[2],"IO")
        return "IO"
    return fixed.get(top,"G")
def resolve_module(mod):
    if not mod or not mod.startswith("astropy"): return None
    q=mod.replace(".","/")
    if q+".py" in all_paths: return q+".py"
    if q+"/__init__.py" in all_paths: return q+"/"
    return None
def py_info(p,txt):
    try: tree=ast.parse(txt)
    except SyntaxError: return None,[],[],[]
    defs=[]; imports=[]; explicit=[]
    for node in tree.body:
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):
            defs.append((node.name,ast.get_docstring(node,clean=False) or "",type(node).__name__))
        elif isinstance(node,ast.Assign):
            for t in node.targets:
                if isinstance(t,ast.Name) and t.id=="__all__" and isinstance(node.value,(ast.List,ast.Tuple)):
                    for e in node.value.elts:
                        if isinstance(e,ast.Constant) and isinstance(e.value,str): explicit.append(e.value)
        elif isinstance(node,ast.ImportFrom):
            if node.level:
                base=list(Path(p).parent.parts)
                for _ in range(max(0,node.level-1)):
                    if base: base.pop()
                mod=".".join(base+((node.module or "").split(".") if node.module else []))
            else: mod=node.module or ""
            rp=resolve_module(mod)
            if rp:
                score=len(node.names)+sum(txt.count(a.name.split(".")[-1]) for a in node.names)
                imports.append((rp,score))
        elif isinstance(node,ast.Import):
            for a in node.names:
                rp=resolve_module(a.name)
                if rp: imports.append((rp,1+txt.count(a.asname or a.name.split(".")[-1])))
    return tree,defs,imports,explicit or [n for n,d,k in defs if not n.startswith("_")]
def related_tests(p,defs):
    path=Path(p); stem=path.stem; cands=[]
    for q in (str(path.parent/"tests"/f"test_{stem}.py"),str(path.parent.parent/"tests"/f"test_{stem}.py")):
        if q in test_text and q not in cands: cands.append(q)
    symbols=[n for n,d,k in defs if not n.startswith("_")][:12]
    for q,txt in test_text.items():
        if q in cands: continue
        hits=sum(1 for s in symbols if re.search(r"'"\\b\"+re.escape(s)+r\"\\b\",txt))
        if (f\"test_{stem}.py\"==Path(q).name or (symbols and hits>=max(1,min(2,len(symbols))))) and (Path(q).parts[:2]==path.parts[:2] or (len(path.parts)>1 and f\"astropy.{path.parts[1]}\" in txt)):
            cands.append(q)
        if len(cands)>=4: break
    return cands[:4]
def test_contracts(p,defs):
    out=[]; symbols=[n for n,d,k in defs if not n.startswith(\"_\")]
    for q in related_tests(p,defs):
        tree=test_tree.get(q); txt=test_text.get(q,\"\")
        if not tree: continue
        for node in tree.body:
            if not isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)) or not node.name.startswith(\"test_\"): continue
            seg=ast.get_source_segment(txt,node) or \"\"
            if symbols and not any(re.search(r\"\\b\"+re.escape(s)+r\"\\b\",seg) for s in symbols) and Path(p).stem not in seg: continue
            expectation=\"\"
            for sub in ast.walk(node):
                if isinstance(sub,ast.Assert):
                    expectation=ast.get_source_segment(txt,sub.test) or \"\"; break
                if isinstance(sub,ast.With):
                    for it in sub.items:
                        ce=it.context_expr
                        if isinstance(ce,ast.Call) and isinstance(ce.func,ast.Attribute) and ce.func.attr==\"raises\":
                            expectation=\"抛出 \"+clean(ast.get_source_segment(txt,ce) or \"指定异常\",130); break
                    if expectation: break
            if expectation:
                out.append(f\"必须保持 {clean(expectation,170)}（{node.name}）\")
                if len(out)>=2: return out
    return out
def c_info(p,txt):
    names=[]
    pats=[r\"(?m)"'^[A-Za-z_]['"\\w\\s\\*]*?\\b([A-Za-z_]\\w*)\\s*\\(["'^;{}]*'"\\)\\s*[;{]\",r\"(?m)"'^(?:cdef|cpdef|def)'"\\s+(?:\\w+\\s+)?(\\w+)\\s*\\(\"]
    for pat in pats:
        for n in re.findall(pat,txt):
            if n not in {\"if\",\"for\",\"while\",\"switch\"} and not n.startswith(\"_\") and n not in names: names.append(n)
    inc=[]
    for h in re.findall(r'#\\s*include\\s*\"(["'^"]+)"'"',txt):
        candidates=[x for x in all_paths if x.endswith(\"/\"+h) or x==h]
        if candidates:
            same=sorted(candidates,key=lambda x:(0 if str(Path(p).parent) in x else 1,len(x)))
            inc.append((same[0],2))
    comment=\"\"
    m=re.search(r\"/\\*\\*?(.*?)\\*/\",txt,re.S)
    if m: comment=first_sentence(re.sub(r\""'^'"\\s*\\* ?\",\"\",m.group(1),flags=re.M))
    return names,inc,comment
def fixture_refs(p):
    name=Path(p).name; refs=[]
    for q,txt in test_text.items():
        if name in txt:
            refs.append(q)
            if len(refs)>=3: break
    return refs
def outline(p):
    path=Path(p); ext=path.suffix.lower(); data=path.read_bytes(); txt=data.decode(\"utf-8\",\"replace\"); lines=txt.splitlines(); mod=module_for(p)
    is_test=\"/tests/\" in p and ext==\".py\"
    is_fixture=(\"/tests/data/\" in p or \"/data/\" in p) and ext not in {\".py\",\".c\",\".h\",\".pyx\"}
    is_build=(path.name in {\"pyproject.toml\",\"setup.py\",\"tox.ini\",\"MANIFEST.in\",\"GNUmakefile\",\"configure\",\"configure.ac\"} or \"setup_package\" in path.name or p.startswith((\".github/\",\".circleci/\")) or ext in {\".yml\",\".yaml\",\".toml\",\".ini\"})
    layer=\"D\" if is_fixture else \"T\" if is_test or path.name==\"conftest.py\" else \"B\" if is_build else \"E\" if path.name==\"__init__.py\" or \"/scripts/\" in p else \"C\" if path.name in {\"core.py\",\"base.py\",\"quantity.py\",\"table.py\",\"wcs.py\",\"modeling.py\"} else \"I\" if ext in {\".c\",\".h\",\".pyx\"} else \"X\" if path.name.startswith(\".\") or ext in {\".cfg\"} else \"S\"
    feats=[]; low=p.lower()
    if ext in {\".c\",\".h\",\".pyx\"}: feats.append(\"C\")
    if any(x in low for x in (\"parser\",\"parse\",\"format\",\"lexer\",\"yacc\",\"lex.\")): feats.append(\"P\")
    if \"registry\" in low or \"connect.py\" in low: feats.append(\"R\")
    if mod==\"VI\": feats.append(\"V\")
    if is_fixture: feats.append(\"D\")
    feats=list(dict.fromkeys(feats))[:2]
    defs=[]; imports=[]; public=[]; doc=\"\"; role=\"\"; api=\"-\"; constraints=[]
    if ext==\".py\":
        tree,defs,imports,public=py_info(p,txt)
        if tree is not None: doc=ast.get_docstring(tree,clean=False) or \"\"
        if is_test:
            target=path.stem.removeprefix(\"test_\").replace(\"_\",\" \"); d=first_sentence(doc)
            role=f\"验证 {mod} 模块的 {target} 行为\"+(f\"，重点为 {d}\" if d and \"license\" not in d.lower() else \"\")
        elif path.name==\"conftest.py\":
            names=[n for n,d,k in defs if not n.startswith(\"_\")]
            role=f\"为 {mod} 测试提供 pytest 配置、夹具与钩子\"+(f\"，包括{','.join(names[:6])}\" if names else \"\")
